head.script:
scwin.onpageload = function() {
	document.title = "CheckCombobox";

	 //DataList dlt_exam_code에 데이터 할당
    dlt_exam_code.setJSON([
        {"label":"Apple","code":"01"},
        {"label":"Pear","code":"02"},
        {"label":"Grapes","code":"03"},
        {"label":"Melon","code":"04"},
        {"label":"Peach","code":"05"}
    ]);
};

	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('ccb_samp_itemTable_main').getAttribute('role') == 'listbox';
	}
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('ccb_samp_itemTable_0').getAttribute('aria-checked') === null;
	}	
	scwin.checkVal3 = function() {
		return WebSquare.wUnit.getDomById('ccb_samp_itemTable_0').getAttribute('role') == 'option';
	}		
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('ccb_samp').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
